begin transaction read only;
select jsonb_build_object(
 'checked_at',now(),
 'pilot',(select to_jsonb(s) from public.platform_settings s where id),
 'store_states',(select jsonb_agg(jsonb_build_object('status',status,'paused',paused,'open_override',open_override,'delivery_enabled',delivery_enabled,'pickup_enabled',pickup_enabled,'count',n)) from (select status,paused,open_override,delivery_enabled,pickup_enabled,count(*) n from public.stores group by 1,2,3,4,5) s),
 'dan',(select jsonb_build_object('exists',true,'status',s.status,'paused',s.paused,'open_override',s.open_override,'delivery_enabled',s.delivery_enabled,'pickup_enabled',s.pickup_enabled,'has_address',s.street<>'' and s.number<>'','category_count',(select count(*) from public.store_categories where store_id=s.id),'active_zones',(select count(*) from public.delivery_zones where store_id=s.id and active),'products',(select count(*) from public.products where store_id=s.id),'groups',(select count(*) from public.product_option_groups g join public.products p on p.id=g.product_id where p.store_id=s.id),'options',(select count(*) from public.product_options o join public.product_option_groups g on g.id=o.group_id join public.products p on p.id=g.product_id where p.store_id=s.id),'orders',(select count(*) from public.orders where store_id=s.id),'store_hash',md5(to_jsonb(s)::text),'products_hash',(select md5(coalesce(jsonb_agg(to_jsonb(p) order by p.id)::text,'')) from public.products p where store_id=s.id),'groups_hash',(select md5(coalesce(jsonb_agg(to_jsonb(g) order by g.id)::text,'')) from public.product_option_groups g join public.products p on p.id=g.product_id where p.store_id=s.id),'options_hash',(select md5(coalesce(jsonb_agg(to_jsonb(o) order by o.id)::text,'')) from public.product_options o join public.product_option_groups g on g.id=o.group_id join public.products p on p.id=g.product_id where p.store_id=s.id)) from public.stores s where s.id='40bac4d9-2e3c-4f1d-b33b-ab9628176136'),
 'migrations',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'execute'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute'),'fixed_search_path',p.proconfig)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and ((n.nspname='public' and p.proname like 'nf_%') or (n.nspname='private' and p.proname in('store_open','require_store','require_user')))),
 'unprotected_tables',(select coalesce(jsonb_agg(n.nspname||'.'||c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind in('r','p') and not c.relrowsecurity),
 'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname in('public','private') or (schemaname='storage' and tablename='objects')),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets),
 'realtime',(select coalesce(jsonb_agg(schemaname||'.'||tablename),'[]') from pg_publication_tables where pubname='supabase_realtime'),
 'order_count',(select count(*) from public.orders)
) as audit;
rollback;
